const handler = {
  get(target, key, receiver) {
    // 開發者試圖直接從 receiver 讀取以確保原型鏈正確
    return receiver[key];
  }
};

const proxy = new Proxy({ count: 1 }, handler);
console.log(proxy.count);

const map = new Map();
const proxy = new Proxy(map, {
  get(target, key, receiver) {
    return Reflect.get(target, key, receiver);
  }
});

proxy.set('key', 'value');

const p = new Proxy([], {
  get(target, key) { console.log('get', key); return Reflect.get(target, key); },
  set(target, key, value) { console.log('set', key); return Reflect.set(target, key, value); }
});

p.push(1);
